// Joins class names and skips empty values.
// cn('px-2', isActive && 'bg-primary', null) -> 'px-2 bg-primary'
export function cn(...classes) {
  return classes.filter(Boolean).join(' ')
}

import { Link } from 'react-router-dom'
import { Loader2 } from 'lucide-react'
import { cn } from '../../lib/cn'

const variants = {
  primary: 'bg-primary text-white shadow-[inset_0_-2px_0_rgba(0,0,0,0.18)] hover:bg-primary-dark',
  secondary: 'border border-line bg-white text-ink hover:bg-canvas',
  ghost: 'text-ink hover:bg-black/5',
  link: 'px-0! text-primary hover:underline',
  danger: 'bg-danger text-white hover:bg-[#9a1d14]',
  'danger-outline': 'border border-danger/40 bg-white text-danger hover:bg-danger-soft',
}

const sizes = {
  sm: 'h-8 px-3 text-xs',
  md: 'h-10 px-4 text-sm',
  lg: 'h-12 px-5 text-[15px]',
}

/**
 * Button used everywhere in the app.
 *
 * <Button>Save</Button>
 * <Button variant="secondary" size="sm" icon={Bookmark}>Save</Button>
 * <Button to="/signup">Sign up</Button>            // renders a router Link
 * <Button loading>Submitting...</Button>
 */
export default function Button({
  variant = 'primary',
  size = 'md',
  icon: Icon,
  iconRight: IconRight,
  loading = false,
  fullWidth = false,
  to,
  className,
  children,
  disabled,
  type = 'button',
  ...rest
}) {
  const classes = cn(
    'inline-flex items-center justify-center gap-2 rounded-lg font-semibold whitespace-nowrap transition-colors',
    'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary',
    'disabled:opacity-50',
    variants[variant],
    sizes[size],
    fullWidth && 'w-full',
    className,
  )

  const content = (
    <>
      {loading ? <Loader2 className="size-4 animate-spin" /> : Icon && <Icon className="size-4" />}
      {children}
      {IconRight && <IconRight className="size-4" />}
    </>
  )

  if (to) {
    return (
      <Link to={to} className={classes} {...rest}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} disabled={disabled || loading} {...rest}>
      {content}
    </button>
  )
}

import { useId } from 'react'
import { cn } from '../../lib/cn'

/**
 * Wraps any input with a label, an optional hint and an error message.
 * The error is shown under the field in red (NFR-4: errors next to the field).
 *
 * <FormField label="Email" error={errors.email}>
 *   {(id) => <input id={id} ... />}
 * </FormField>
 */
export default function FormField({ label, hint, error, required, className, children }) {
  const id = useId()
  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      {label && (
        <label htmlFor={id} className="text-[13px] font-semibold text-ink">
          {label}
          {required && <span className="ml-0.5 text-danger">*</span>}
        </label>
      )}
      {typeof children === 'function' ? children(id) : children}
      {error ? (
        <p className="text-xs text-danger" role="alert">
          {error}
        </p>
      ) : (
        hint && <p className="text-xs text-muted">{hint}</p>
      )}
    </div>
  )
}

// shared look for text inputs, selects and textareas
export function fieldClasses(error, extra) {
  return cn(
    'w-full rounded-lg border bg-white px-3 text-sm text-ink placeholder:text-muted/70',
    'transition-colors focus:outline-none focus:ring-2',
    error
      ? 'border-danger/50 bg-danger-soft/60 focus:ring-danger/20'
      : 'border-line focus:border-primary focus:ring-primary/15',
    'disabled:bg-canvas disabled:text-muted',
    extra,
  )
}

import { useState } from 'react'
import { Eye, EyeOff } from 'lucide-react'
import FormField, { fieldClasses } from './FormField'
import { cn } from '../../lib/cn'

/**
 * Text input with label + error.
 *
 * <Input label="Email" icon={Mail} value={email} onChange={(e) => setEmail(e.target.value)} error={errors.email} />
 * <Input label="Password" type="password" ... />   // gets a show/hide eye button
 */
export default function Input({ label, hint, error, required, icon: Icon, type = 'text', className, inputClassName, ...rest }) {
  const [visible, setVisible] = useState(false)
  const isPassword = type === 'password'

  return (
    <FormField label={label} hint={hint} error={error} required={required} className={className}>
      {(id) => (
        <div className="relative">
          {Icon && <Icon className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted" />}
          <input
            id={id}
            type={isPassword && visible ? 'text' : type}
            aria-invalid={Boolean(error)}
            className={fieldClasses(error, cn('h-11', Icon && 'pl-9', isPassword && 'pr-10', inputClassName))}
            {...rest}
          />
          {isPassword && (
            <button
              type="button"
              onClick={() => setVisible((v) => !v)}
              className="absolute top-1/2 right-3 -translate-y-1/2 text-muted hover:text-ink"
              aria-label={visible ? 'Hide password' : 'Show password'}
            >
              {visible ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
            </button>
          )}
        </div>
      )}
    </FormField>
  )
}

import { ChevronDown } from 'lucide-react'
import FormField, { fieldClasses } from './FormField'

/**
 * Native select with the app styling.
 * options can be strings or { value, label } objects.
 *
 * <Select label="City" value={city} onChange={(e) => setCity(e.target.value)}
 *         options={CITIES} placeholder="All cities" />
 */
export default function Select({ label, hint, error, required, options = [], placeholder, className, ...rest }) {
  return (
    <FormField label={label} hint={hint} error={error} required={required} className={className}>
      {(id) => (
        <div className="relative">
          <select
            id={id}
            aria-invalid={Boolean(error)}
            className={fieldClasses(error, 'h-11 appearance-none pr-9')}
            {...rest}
          >
            {placeholder !== undefined && <option value="">{placeholder}</option>}
            {options.map((opt) => {
              const value = typeof opt === 'string' ? opt : opt.value
              const text = typeof opt === 'string' ? opt : opt.label
              return (
                <option key={value} value={value}>
                  {text}
                </option>
              )
            })}
          </select>
          <ChevronDown className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2 text-muted" />
        </div>
      )}
    </FormField>
  )
}

import FormField, { fieldClasses } from './FormField'

/**
 * Multi-line text input. Pass maxLength to show a character counter.
 *
 * <Textarea label="Short bio" rows={4} maxLength={300} value={bio} onChange={...} />
 */
export default function Textarea({ label, hint, error, required, className, rows = 4, maxLength, value = '', ...rest }) {
  const counter = maxLength ? `${String(value).length}/${maxLength}` : null
  return (
    <FormField label={label} hint={hint ?? counter} error={error} required={required} className={className}>
      {(id) => (
        <textarea
          id={id}
          rows={rows}
          maxLength={maxLength}
          value={value}
          aria-invalid={Boolean(error)}
          className={fieldClasses(error, 'resize-y py-2.5 leading-relaxed')}
          {...rest}
        />
      )}
    </FormField>
  )
}

import { cn } from '../../lib/cn'

/**
 * <Checkbox checked={agree} onChange={(e) => setAgree(e.target.checked)} label="I agree" />
 * label can be a string or JSX.
 */
export default function Checkbox({ label, error, className, ...rest }) {
  return (
    <div className={className}>
      <label className="inline-flex cursor-pointer items-start gap-2 text-[13px] text-body">
        <input
          type="checkbox"
          className={cn('mt-0.5 size-4 shrink-0 cursor-pointer rounded accent-primary', error && 'outline outline-danger')}
          {...rest}
        />
        {label && <span>{label}</span>}
      </label>
      {error && <p className="mt-1 text-xs text-danger">{error}</p>}
    </div>
  )
}

import { cn } from '../../lib/cn'

/**
 * On/off switch (used in settings and reminder switches).
 *
 * <Toggle checked={on} onChange={setOn} label="In-app notifications" />
 * onChange receives the new boolean value.
 */
export default function Toggle({ checked, onChange, label, disabled, className }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      onClick={() => onChange(!checked)}
      className={cn(
        'relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors',
        checked ? 'bg-primary' : 'bg-[#cfd3d1]',
        disabled && 'opacity-50',
        className,
      )}
    >
      <span
        className={cn(
          'inline-block size-[18px] rounded-full bg-white shadow transition-transform',
          checked ? 'translate-x-[23px]' : 'translate-x-[3px]',
        )}
      />
    </button>
  )
}

