            className={fieldClasses(error, cn('h-11', Icon && 'pl-9', isPassword && 'pr-10', inputClassName))}
            {...rest}
          />
          {isPassword && (
            <button
              type="button"
              onClick={() => setVisible((v) => !v)}
              className="absolute top-1/2 right-3 -translate-y-1/2 text-muted hover:text-ink"
              aria-label={visible ? 'Hide password' : 'Show password'}
            >
              {visible ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
            </button>
          )}
        </div>
      )}
    </FormField>
  )
}

import { ChevronDown } from 'lucide-react'
import FormField, { fieldClasses } from './FormField'

/**
 * Native select with the app styling.
 * options can be strings or { value, label } objects.
 *
 * <Select label="City" value={city} onChange={(e) => setCity(e.target.value)}
 *         options={CITIES} placeholder="All cities" />
 */
export default function Select({ label, hint, error, required, options = [], placeholder, className, ...rest }) {
  return (
    <FormField label={label} hint={hint} error={error} required={required} className={className}>
      {(id) => (
        <div className="relative">
          <select
            id={id}
            aria-invalid={Boolean(error)}
            className={fieldClasses(error, 'h-11 appearance-none pr-9')}
            {...rest}
          >
            {placeholder !== undefined && <option value="">{placeholder}</option>}
            {options.map((opt) => {
              const value = typeof opt === 'string' ? opt : opt.value
              const text = typeof opt === 'string' ? opt : opt.label
              return (
                <option key={value} value={value}>
                  {text}
                </option>
              )
            })}
          </select>
          <ChevronDown className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2 text-muted" />
        </div>
      )}
    </FormField>
  )
}

import FormField, { fieldClasses } from './FormField'

/**
 * Multi-line text input. Pass maxLength to show a character counter.
 *
 * <Textarea label="Short bio" rows={4} maxLength={300} value={bio} onChange={...} />
 */
export default function Textarea({ label, hint, error, required, className, rows = 4, maxLength, value = '', ...rest }) {
  const counter = maxLength ? `${String(value).length}/${maxLength}` : null
  return (
    <FormField label={label} hint={hint ?? counter} error={error} required={required} className={className}>
      {(id) => (
        <textarea
          id={id}
          rows={rows}
          maxLength={maxLength}
          value={value}
          aria-invalid={Boolean(error)}
          className={fieldClasses(error, 'resize-y py-2.5 leading-relaxed')}
          {...rest}
        />
      )}
    </FormField>
  )
}

import { cn } from '../../lib/cn'

/**
 * <Checkbox checked={agree} onChange={(e) => setAgree(e.target.checked)} label="I agree" />
 * label can be a string or JSX.
 */
export default function Checkbox({ label, error, className, ...rest }) {
  return (
    <div className={className}>
      <label className="inline-flex cursor-pointer items-start gap-2 text-[13px] text-body">
        <input
          type="checkbox"
          className={cn('mt-0.5 size-4 shrink-0 cursor-pointer rounded accent-primary', error && 'outline outline-danger')}
          {...rest}
        />
        {label && <span>{label}</span>}
      </label>
      {error && <p className="mt-1 text-xs text-danger">{error}</p>}
    </div>
  )
}

import { cn } from '../../lib/cn'

/**
 * On/off switch (used in settings and reminder switches).
 *
 * <Toggle checked={on} onChange={setOn} label="In-app notifications" />
 * onChange receives the new boolean value.
 */
export default function Toggle({ checked, onChange, label, disabled, className }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      onClick={() => onChange(!checked)}
      className={cn(
        'relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors',
        checked ? 'bg-primary' : 'bg-[#cfd3d1]',
        disabled && 'opacity-50',
        className,
      )}
    >
      <span
        className={cn(
          'inline-block size-[18px] rounded-full bg-white shadow transition-transform',
          checked ? 'translate-x-[23px]' : 'translate-x-[3px]',
        )}
      />
    </button>
  )
}

