import { cn } from '../../lib/cn'

const tones = {
  neutral: 'bg-[#efefec] text-body',
  teal: 'bg-primary-soft text-primary',
  success: 'bg-success-soft text-success',
  warning: 'bg-warning-soft text-warning',
  danger: 'bg-danger-soft text-danger',
  info: 'bg-info-soft text-info',
  dark: 'bg-night text-white',
}

/**
 * Small rounded label.
 * <Badge>Co-op</Badge>
 * <Badge tone="teal">Strong match</Badge>
 * <Badge tone="warning" icon={Clock}>Closes soon</Badge>
 */
export default function Badge({ tone = 'neutral', icon: Icon, className, children }) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-[11px] font-semibold whitespace-nowrap',
        tones[tone],
        className,
      )}
    >
      {Icon && <Icon className="size-3" />}
      {children}
    </span>
  )
}

import Badge from './Badge'
import { APP_STATUS } from '../../lib/constants'

// colour for each application status (Phase 3 status list)
const toneByStatus = {
  [APP_STATUS.APPLIED]: 'neutral',
  [APP_STATUS.UNDER_REVIEW]: 'info',
  [APP_STATUS.SHORT_LISTED]: 'teal',
  [APP_STATUS.ACCEPTED]: 'success',
  [APP_STATUS.REJECTED]: 'danger',
  [APP_STATUS.WITHDRAWN]: 'neutral',
}

/**
 * <StatusBadge status={application.status} />
 * Works with every value in APP_STATUS. Unknown values fall back to grey.
 */
export default function StatusBadge({ status, className }) {
  return (
    <Badge tone={toneByStatus[status] ?? 'neutral'} className={className}>
      {status}
    </Badge>
  )
}

import { cn } from '../../lib/cn'

/**
 * White rounded box with a light border.
 * <Card className="p-6">...</Card>
 * <Card title="Recent applications" subtitle="Your latest activity" action={<Link>View</Link>}>...</Card>
 */
export default function Card({ title, subtitle, action, className, bodyClassName, children }) {
  return (
    <section className={cn('rounded-xl border border-line bg-white', className)}>
      {(title || action) && (
        <header className="flex flex-wrap items-start justify-between gap-3 px-5 pt-5 sm:px-6">
          <div>
            {title && <h2 className="text-xl font-bold text-ink">{title}</h2>}
            {subtitle && <p className="mt-0.5 text-xs text-muted">{subtitle}</p>}
          </div>
          {action}
        </header>
      )}
      <div className={cn(title || action ? 'p-5 sm:p-6' : '', bodyClassName)}>{children}</div>
    </section>
  )
}

import { useEffect } from 'react'
import { createPortal } from 'react-dom'
import { X } from 'lucide-react'
import { cn } from '../../lib/cn'

/**
 * Centered dialog with a dark overlay. Closes on Escape and on overlay click.
 *
 * <Modal open={isOpen} onClose={() => setOpen(false)} title="Add external application">
 *   ...form...
 * </Modal>
 *
 * size: 'sm' | 'md' | 'lg'
 * footer: optional JSX shown at the bottom (buttons)
 */
export default function Modal({ open, onClose, title, description, size = 'md', footer, children, className }) {
  useEffect(() => {
    if (!open) return
    const onKey = (e) => e.key === 'Escape' && onClose?.()
    document.addEventListener('keydown', onKey)
    const prevOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = prevOverflow
    }
  }, [open, onClose])

  if (!open) return null

  const widths = { sm: 'max-w-md', md: 'max-w-lg', lg: 'max-w-2xl' }

  return createPortal(
    <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center sm:p-4">
      <div className="absolute inset-0 bg-night/50 backdrop-blur-[2px]" onClick={onClose} />
      <div
        role="dialog"
        aria-modal="true"
        className={cn(
          'relative flex max-h-[92vh] w-full flex-col rounded-t-2xl bg-white shadow-2xl sm:rounded-2xl',
          widths[size],
          className,
        )}
      >
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="absolute top-4 right-4 grid size-8 place-items-center rounded-full bg-canvas text-muted hover:text-ink"
          >
            <X className="size-4" />
          </button>
        )}
        {(title || description) && (
          <div className="px-6 pt-6 pr-14">
            {title && <h2 className="text-2xl font-bold">{title}</h2>}
            {description && <p className="mt-1 text-sm text-muted">{description}</p>}
          </div>
        )}
        <div className="overflow-y-auto px-6 py-5">{children}</div>
        {footer && <div className="flex flex-wrap justify-end gap-2 border-t border-line px-6 py-4">{footer}</div>}
      </div>
    </div>,
    document.body,
  )
}

import { useState } from 'react'
import Modal from './Modal'
import Button from './Button'
import Textarea from './Textarea'

/**
 * "Are you sure?" dialog. Use it for every action that can't be undone
 * (withdraw, close posting, approve shortlist, suspend user ...).
 *
 * <ConfirmDialog
 *   open={open}
 *   title="Withdraw application?"
 *   message="You won't be able to apply to this posting again."
 *   confirmLabel="Withdraw"
 *   danger
 *   onConfirm={() => { ...; setOpen(false) }}
 *   onCancel={() => setOpen(false)}
 * />
 *
 * requireReason: shows a textarea and passes the text to onConfirm(reason).
 * The confirm button stays disabled until a reason is typed.
 */
export default function ConfirmDialog({
  open,
  title,
  message,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  danger = false,
  requireReason = false,
  reasonLabel = 'Reason',
  reasonPlaceholder = 'Explain the reason...',
  onConfirm,
  onCancel,
  children,
}) {
  const [reason, setReason] = useState('')

  const close = () => {
    setReason('')
    onCancel?.()
  }

  const confirm = () => {
    onConfirm?.(reason.trim())
    setReason('')
  }

  return (
    <Modal
      open={open}
      onClose={close}
      title={title}
      size="sm"
      footer={
        <>
          <Button variant="secondary" onClick={close}>
            {cancelLabel}
          </Button>
          <Button variant={danger ? 'danger' : 'primary'} onClick={confirm} disabled={requireReason && !reason.trim()}>
            {confirmLabel}
          </Button>
        </>
      }
    >
      {message && <p className="text-sm leading-relaxed text-body">{message}</p>}
      {children}
      {requireReason && (
        <Textarea
          className="mt-4"
          label={reasonLabel}
          required
          rows={3}
          maxLength={300}
          placeholder={reasonPlaceholder}
          value={reason}
          onChange={(e) => setReason(e.target.value)}
        />
      )}
    </Modal>
  )
}

import { Inbox } from 'lucide-react'
import { cn } from '../../lib/cn'

/**
 * Shown when a list is empty ("No applications yet", "You're all caught up").
 *
 * <EmptyState icon={Bookmark} title="You haven't saved any listings yet"
 *   message="Save listings to come back to them later."
 *   action={<Button to="/student/search">Search listings</Button>} />
 */
export default function EmptyState({ icon: Icon = Inbox, title, message, action, className }) {
  return (
    <div className={cn('flex flex-col items-center px-6 py-12 text-center', className)}>
      <div className="grid size-12 place-items-center rounded-full bg-primary-soft text-primary">
        <Icon className="size-5" />
      </div>
      <h3 className="mt-4 text-lg font-bold">{title}</h3>
      {message && <p className="mt-1 max-w-sm text-sm text-muted">{message}</p>}
      {action && <div className="mt-5">{action}</div>}
    </div>
  )
}

/**
 * Top of every logged-in page: eyebrow + big serif title + subtitle + optional buttons on the right.
 *
 * <PageHeader eyebrow="Student workspace" title="My applications"
 *   subtitle="Track every application in one place."
 *   actions={<Button icon={Plus}>Add external application</Button>} />
 */
export default function PageHeader({ eyebrow, title, subtitle, actions }) {
  return (
    <div className="mb-6 flex flex-col gap-4 sm:mb-8 sm:flex-row sm:items-end sm:justify-between">
      <div>
        {eyebrow && <p className="eyebrow">{eyebrow}</p>}
        <h1 className="mt-2 text-3xl leading-tight sm:text-[40px]">{title}</h1>
        {subtitle && <p className="mt-1.5 text-sm text-muted">{subtitle}</p>}
      </div>
      {actions && <div className="flex flex-wrap gap-2">{actions}</div>}
    </div>
  )
}

/**
 * Number tile used on dashboards and statistics.
 * <StatCard icon={Briefcase} value={3} label="Active postings" note="+1 this month" />
 */
export default function StatCard({ icon: Icon, value, label, note }) {
  return (
    <div className="flex items-start gap-3 rounded-xl border border-line bg-white p-4">
      {Icon && (
        <div className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary-soft text-primary">
          <Icon className="size-4" />
        </div>
      )}
      <div className="min-w-0">
        <p className="font-serif text-2xl leading-none font-bold">{value}</p>
        <p className="mt-1 text-xs text-body">{label}</p>
        {note && <p className="mt-2 text-[11px] text-primary">{note}</p>}
      </div>
    </div>
  )
}

import { cn } from '../../lib/cn'
import { initials } from '../../lib/format'

/**
 * Initials in a box (companies) or a circle (people), like the prototype ("AD", "NA").
 *
 * <Avatar name="Aramco Digital" />                 // square, light grey
 * <Avatar name="Nora Alqahtani" round dark />      // round, teal
 * <Avatar name="stc" text="stc" />                 // custom text
 * <Avatar src={logoDataUrl} name="Tamara" />      // shows an uploaded logo
 */
export default function Avatar({ name = '', text, src, round = false, dark = false, size = 'md', className }) {
  const sizes = { sm: 'size-8 text-[11px]', md: 'size-10 text-xs', lg: 'size-14 text-sm' }
  return (
    <div
      className={cn(
        'grid shrink-0 place-items-center overflow-hidden font-bold',
        round ? 'rounded-full' : 'rounded-lg border border-line',
        dark ? 'bg-primary text-white' : 'bg-[#f0f0ed] text-ink',
        sizes[size],
        className,
      )}
      aria-hidden="true"
    >
