}

import { useRef, useState } from 'react'
import { FileText, UploadCloud } from 'lucide-react'
import { cn } from '../../lib/cn'

/**
 * Click-or-drop file picker that validates type and size before calling onFile.
 *
 * Resume (FR-S1):  <FileUpload accept={['application/pdf']} maxSizeMB={5}
 *                    typeError="Please upload a PDF under 5 MB." onFile={handleFile} />
 * Logo (FR-C1):    <FileUpload accept={['image/png', 'image/jpeg']} maxSizeMB={2} ... />
 *
 * onFile(file, dataUrl) is called only when the file is valid.
 * dataUrl is a base64 string you can store in the data store and show later.
 * Errors are shown inside the component (and also passed to onError if given).
 */
export default function FileUpload({
  accept = [],
  maxSizeMB = 5,
  label = 'Click to upload or drag and drop',
  helper,
  typeError,
  currentFileName,
  onFile,
  onError,
  className,
}) {
  const inputRef = useRef(null)
  const [error, setError] = useState('')
  const [dragging, setDragging] = useState(false)

  const fail = (message) => {
    setError(message)
    onError?.(message)
  }

  const handle = (file) => {
    if (!file) return
    const tooBig = file.size > maxSizeMB * 1024 * 1024
    const wrongType = accept.length > 0 && !accept.includes(file.type)
    if (wrongType || tooBig) {
      fail(typeError ?? `File must be ${accept.join(' or ')} and under ${maxSizeMB} MB.`)
      return
    }
    setError('')
    const reader = new FileReader()
    reader.onload = () => onFile?.(file, reader.result)
    reader.readAsDataURL(file)
  }

  return (
    <div className={className}>
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault()
          setDragging(true)
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => {
          e.preventDefault()
          setDragging(false)
          handle(e.dataTransfer.files?.[0])
        }}
        className={cn(
          'flex w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed px-4 py-6 text-center transition-colors',
          error ? 'border-danger/50 bg-danger-soft/50' : dragging ? 'border-primary bg-primary-soft' : 'border-line bg-canvas hover:border-primary/50',
        )}
      >
        {currentFileName ? <FileText className="size-6 text-primary" /> : <UploadCloud className="size-6 text-muted" />}
        <span className="text-sm font-medium text-ink">{currentFileName ?? label}</span>
        {helper && <span className="text-xs text-muted">{helper}</span>}
      </button>
      <input
        ref={inputRef}
        type="file"
        accept={accept.join(',')}
        className="hidden"
        onChange={(e) => {
          handle(e.target.files?.[0])
          e.target.value = ''
        }}
      />
      {error && (
        <p className="mt-1.5 text-xs text-danger" role="alert">
          {error}
        </p>
      )}
    </div>
  )
}

import { AlertCircle, CheckCircle2, Info, TriangleAlert } from 'lucide-react'
import { cn } from '../../lib/cn'

const styles = {
  info: { box: 'border-info/20 bg-info-soft text-info', icon: Info },
  success: { box: 'border-success/20 bg-success-soft text-success', icon: CheckCircle2 },
  warning: { box: 'border-warning/25 bg-warning-soft text-warning', icon: TriangleAlert },
  danger: { box: 'border-danger/20 bg-danger-soft text-danger', icon: AlertCircle },
}

/**
 * Inline message box.
 * <Alert tone="danger" title="Account temporarily locked">Too many attempts...</Alert>
 * <Alert tone="info">Showing keyword results only</Alert>
 */
export default function Alert({ tone = 'info', title, icon, children, action, className }) {
  const { box, icon: DefaultIcon } = styles[tone]
  const Icon = icon ?? DefaultIcon
  return (
    <div className={cn('flex gap-3 rounded-lg border px-4 py-3 text-[13px]', box, className)} role="status">
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div className="min-w-0 flex-1">
        {title && <p className="font-semibold">{title}</p>}
        {children && <div className={cn('text-body', title && 'mt-0.5')}>{children}</div>}
      </div>
      {action}
    </div>
  )
}

import { cn } from '../../lib/cn'

/**
 * Simple table styling that matches the prototype (grey header, thin row lines).
 * On small screens the table scrolls sideways instead of breaking the layout.
 *
 * <Table>
 *   <thead><tr><Th>Company</Th><Th>City</Th></tr></thead>
 *   <tbody><tr><Td>Aramco</Td><Td>Dhahran</Td></tr></tbody>
 * </Table>
 */
export function Table({ className, children }) {
  return (
    <div className={cn('overflow-x-auto rounded-xl border border-line bg-white', className)}>
      <table className="w-full min-w-[640px] border-collapse text-left text-sm">{children}</table>
    </div>
  )
}

export function Th({ className, children, ...rest }) {
  return (
    <th
      className={cn('bg-[#f2f2ef] px-4 py-3 text-[10px] font-semibold tracking-wider text-muted uppercase', className)}
      {...rest}
    >
      {children}
    </th>
  )
}

export function Td({ className, children, ...rest }) {
  return (
    <td className={cn('border-t border-line px-4 py-3 align-middle text-body', className)} {...rest}>
      {children}
    </td>
  )
}

import { Loader2 } from 'lucide-react'
import { cn } from '../../lib/cn'

// <Spinner label="We're analysing your resume" />
export default function Spinner({ label, className }) {
  return (
    <div className={cn('flex items-center gap-2 text-sm text-muted', className)}>
      <Loader2 className="size-4 animate-spin text-primary" />
      {label}
    </div>
  )
}

// Small helpers for showing dates and text. All dates in the store are ISO strings.

const DAY = 24 * 60 * 60 * 1000

// "Nora Alqahtani" -> "NA", "stc" -> "ST"
export function initials(name = '') {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return '?'
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return (parts[0][0] + parts[1][0]).toUpperCase()
}

// "Jun 30, 2026"
export function formatDate(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

// "September 1, 2026"
export function formatLongDate(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
}

// "Jun 30, 2026, 10:42 AM"
export function formatDateTime(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
}

// whole days from today until the date (negative if it already passed)
export function daysUntil(iso) {
  const start = new Date()
  start.setHours(0, 0, 0, 0)
  const end = new Date(iso)
  end.setHours(0, 0, 0, 0)
  return Math.round((end - start) / DAY)
}

// "2 days ago", "Yesterday", "20 minutes ago"
export function timeAgo(iso) {
  const diff = Date.now() - new Date(iso).getTime()
  const minutes = Math.floor(diff / 60000)
  if (minutes < 1) return 'Just now'
  if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`
  const days = Math.floor(hours / 24)
  if (days === 1) return 'Yesterday'
  if (days < 7) return `${days} days ago`
  const weeks = Math.floor(days / 7)
  if (weeks < 5) return `${weeks} week${weeks === 1 ? '' : 's'} ago`
  return formatDate(iso)
}

// "Closes in 2 days" / "Closes today" / "Closed" / "Closes Jun 28"
export function deadlineLabel(iso) {
  const days = daysUntil(iso)
  if (days < 0) return 'Closed'
  if (days === 0) return 'Closes today'
  if (days === 1) return 'Closes tomorrow'
  if (days <= 7) return `Closes in ${days} days`
  return `Closes ${new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`
}

// weeks -> "6 months" / "8 weeks"
export function durationLabel(weeks) {
  if (!weeks) return '-'
  if (weeks % 4 === 0 && weeks >= 8) return `${weeks / 4} months`
  return `${weeks} weeks`
}

// returns an ISO date string N days from now (used by the seed data)
export function daysFromNow(days, hour = 9) {
  const d = new Date()
  d.setDate(d.getDate() + days)
  d.setHours(hour, 0, 0, 0)
  return d.toISOString()
}

// "Good morning" / "Good afternoon" / "Good evening"
export function greeting() {
  const h = new Date().getHours()
  if (h < 12) return 'Good morning'
  if (h < 18) return 'Good afternoon'
  return 'Good evening'
}

