import { Link } from 'react-router-dom'
import { cn } from '../../lib/cn'

// teal "IC" square + wordmark. light = white text for dark backgrounds
export default function Logo({ to = '/', light = false, className }) {
  return (
    <Link to={to} className={cn('flex items-center gap-2.5', className)} aria-label="InternConnect home">
      <span className="grid size-8 place-items-center rounded-lg bg-primary text-[11px] font-bold text-white">IC</span>
      <span className={cn('text-[17px] font-bold tracking-tight', light ? 'text-white' : 'text-ink')}>InternConnect</span>
    </Link>
  )
}

import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Bell } from 'lucide-react'
import { useNotifications } from '../../hooks/useNotifications'
import { useAuth } from '../../context/authContext'
import { ROLES } from '../../lib/constants'
import { timeAgo } from '../../lib/format'
import { cn } from '../../lib/cn'
import { PATHS } from '../../routes/paths'

// Bell icon with unread count and a dropdown of the latest notifications (FR-S10)
export default function NotificationBell() {
  const { items, unreadCount, markRead, markAllRead } = useNotifications()
  const { role } = useAuth()
  const [open, setOpen] = useState(false)
  const ref = useRef(null)
  const navigate = useNavigate()

  useEffect(() => {
    if (!open) return
    const close = (e) => !ref.current?.contains(e.target) && setOpen(false)
    const onKey = (e) => e.key === 'Escape' && setOpen(false)
    document.addEventListener('mousedown', close)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', close)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  const openItem = (n) => {
    markRead(n.id)
    setOpen(false)
    if (n.link) navigate(n.link)
  }

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-label={`Notifications${unreadCount ? `, ${unreadCount} unread` : ''}`}
        className="relative grid size-9 place-items-center rounded-full border border-line bg-white text-ink hover:bg-canvas"
      >
        <Bell className="size-4" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 grid min-w-[18px] place-items-center rounded-full bg-primary px-1 text-[10px] font-bold text-white ring-2 ring-white">
            {unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="fixed inset-x-3 top-16 z-40 overflow-hidden rounded-xl border border-line bg-white shadow-xl sm:absolute sm:inset-x-auto sm:top-12 sm:right-0 sm:w-[340px]">
          <div className="flex items-center justify-between border-b border-line px-4 py-3">
            <p className="text-sm font-semibold">Notifications</p>
            {unreadCount > 0 && (
              <button type="button" onClick={markAllRead} className="text-xs font-medium text-primary hover:underline">
                Mark all as read
              </button>
            )}
          </div>
          {items.length === 0 ? (
            <p className="px-4 py-10 text-center text-sm text-muted">You&apos;re all caught up.</p>
          ) : (
            <ul className="max-h-[360px] overflow-y-auto">
              {items.slice(0, 6).map((n) => (
                <li key={n.id}>
                  <button
                    type="button"
                    onClick={() => openItem(n)}
                    className="flex w-full gap-3 border-b border-line px-4 py-3 text-left last:border-0 hover:bg-canvas"
                  >
                    <span className={cn('mt-1.5 size-2 shrink-0 rounded-full', n.read ? 'bg-transparent' : 'bg-primary')} />
                    <span className="min-w-0">
                      <span className="block text-[13px] font-semibold text-ink">{n.title}</span>
                      <span className="mt-0.5 block text-xs text-body">{n.message}</span>
                      <span className="mt-1 block text-[11px] text-muted">{timeAgo(n.createdAt)}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          )}
          {role === ROLES.STUDENT && (
            <button
              type="button"
              onClick={() => {
                setOpen(false)
                navigate(PATHS.student.notifications)
              }}
              className="w-full border-t border-line py-3 text-center text-[13px] font-semibold text-primary hover:bg-canvas"
            >
              View all notifications
            </button>
          )}
        </div>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { LogOut, Settings, User } from 'lucide-react'
import { useAuth } from '../../context/authContext'
import { useToast } from '../../context/toastContext'
import { ROLES } from '../../lib/constants'
import { PATHS } from '../../routes/paths'
import Avatar from '../ui/Avatar'

const linksByRole = {
  [ROLES.STUDENT]: [
    { label: 'My profile', to: PATHS.student.profile, icon: User },
    { label: 'Settings', to: PATHS.student.settings, icon: Settings },
  ],
  [ROLES.COMPANY]: [{ label: 'Company profile', to: PATHS.company.profile, icon: User }],
  [ROLES.ADMIN]: [],
}

// avatar button that opens the account menu (FR-A5: "opens the account menu and clicks Log out")
export default function AccountMenu() {
  const { user, role, profile, logout } = useAuth()
  const toast = useToast()
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const ref = useRef(null)

  useEffect(() => {
    if (!open) return
    const close = (e) => !ref.current?.contains(e.target) && setOpen(false)
    document.addEventListener('mousedown', close)
    return () => document.removeEventListener('mousedown', close)
  }, [open])

  const doLogout = () => {
    setOpen(false)
    logout()
    toast.info('You have been logged out.')
    navigate(PATHS.home)
  }

  return (
    <div className="relative" ref={ref}>
      <button type="button" onClick={() => setOpen((o) => !o)} aria-label="Account menu" className="rounded-full">
        <Avatar
          name={user.name}
          src={role === ROLES.COMPANY ? profile?.logo : null}
          round
          dark={role === ROLES.STUDENT}
          className={role === ROLES.STUDENT ? '' : 'border-0 bg-night! text-white!'}
        />
      </button>
      {open && (
        <div className="absolute top-12 right-0 z-40 w-56 overflow-hidden rounded-xl border border-line bg-white py-1 shadow-xl">
          <div className="border-b border-line px-4 py-3">
            <p className="truncate text-sm font-semibold">{user.name}</p>
            <p className="truncate text-xs text-muted">{user.email}</p>
          </div>
          {linksByRole[role].map(({ label, to, icon: Icon }) => (
            <Link
              key={to}
              to={to}
              onClick={() => setOpen(false)}
              className="flex items-center gap-2.5 px-4 py-2.5 text-sm text-body hover:bg-canvas hover:text-ink"
            >
              <Icon className="size-4" />
              {label}
            </Link>
          ))}
          <button
            type="button"
            onClick={doLogout}
            className="flex w-full items-center gap-2.5 px-4 py-2.5 text-sm text-danger hover:bg-danger-soft"
          >
            <LogOut className="size-4" />
            Log out
          </button>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { NavLink, useLocation, useNavigate } from 'react-router-dom'
import { Menu, X } from 'lucide-react'
import { useAuth } from '../../context/authContext'
import { useToast } from '../../context/toastContext'
import { ROLES } from '../../lib/constants'
import { cn } from '../../lib/cn'
import { HOME_BY_ROLE, NAV_BY_ROLE, PATHS } from '../../routes/paths'
import Button from '../ui/Button'
import Logo from './Logo'
import NotificationBell from './NotificationBell'
import AccountMenu from './AccountMenu'

function RoleBadge({ role }) {
  return (
    <span className="hidden rounded-full bg-[#efefec] px-3 py-1 text-[10px] font-semibold tracking-[0.12em] text-muted uppercase sm:inline-block">
      {role ?? 'Guest'}
    </span>
  )
}

/**
 * Top navigation bar. The links change with the role (see NAV_BY_ROLE in routes/paths.js).
 * Below 1024px the links move into a menu opened by the hamburger button.
 */
export default function Navbar() {
  const { user, role, logout } = useAuth()
  const toast = useToast()
  const navigate = useNavigate()
  const location = useLocation()
  const [mobileOpen, setMobileOpen] = useState(false)
  const links = NAV_BY_ROLE[role ?? 'guest']

  // close the mobile menu when the page changes
  useEffect(() => setMobileOpen(false), [location.pathname, location.hash])

  const doLogout = () => {
    logout()
    toast.info('You have been logged out.')
    navigate(PATHS.home)
  }

  const linkClass = ({ isActive }, hashLink) =>
    cn(
      'relative flex h-16 items-center text-sm transition-colors',
      isActive && !hashLink
        ? 'font-semibold text-ink after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-primary'
        : 'text-muted hover:text-ink',
    )

  return (
    <header className="sticky top-0 z-30 border-b border-line bg-white">
      <div className="container-page flex h-16 items-center gap-8">
        <Logo to={user ? HOME_BY_ROLE[role] : PATHS.home} />

        <nav className="hidden h-full items-center gap-7 lg:flex" aria-label="Main">
          {links.map((link) => (
            <NavLink key={link.label} to={link.to} end={link.end} className={(s) => linkClass(s, link.to.includes('#'))}>
              {link.label}
            </NavLink>
          ))}
        </nav>

        <div className="ml-auto flex items-center gap-3">
          <RoleBadge role={role} />
          {!user && (
            <>
              <Button variant="ghost" to={PATHS.login} className="hidden sm:inline-flex">
                Log in
              </Button>
              <Button to={PATHS.signup} className="hidden sm:inline-flex">
                Sign up
              </Button>
            </>
          )}
          {user && (
            <>
              {role !== ROLES.ADMIN && <NotificationBell />}
              {role !== ROLES.STUDENT && (
                <Button variant="ghost" onClick={doLogout} className="hidden sm:inline-flex">
                  Log out
                </Button>
              )}
              <AccountMenu />
            </>
          )}
          <button
            type="button"
            onClick={() => setMobileOpen((o) => !o)}
            className="grid size-9 place-items-center rounded-lg border border-line lg:hidden"
            aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
            aria-expanded={mobileOpen}
          >
            {mobileOpen ? <X className="size-4" /> : <Menu className="size-4" />}
          </button>
        </div>
      </div>

      {mobileOpen && (
        <nav className="border-t border-line bg-white lg:hidden" aria-label="Mobile">
          <div className="container-page flex flex-col py-2">
            {links.map((link) => (
              <NavLink
                key={link.label}
                to={link.to}
                end={link.end}
                className={({ isActive }) =>
                  cn(
                    'rounded-lg px-3 py-3 text-sm',
                    isActive && !link.to.includes('#') ? 'bg-primary-soft font-semibold text-primary' : 'text-body',
                  )
                }
              >
                {link.label}
              </NavLink>
            ))}
            {!user && (
              <div className="mt-2 grid grid-cols-2 gap-2 border-t border-line pt-3 pb-1">
                <Button variant="secondary" to={PATHS.login}>
                  Log in
                </Button>
                <Button to={PATHS.signup}>Sign up</Button>
              </div>
            )}
            {user && (
              <button type="button" onClick={doLogout} className="mt-1 rounded-lg px-3 py-3 text-left text-sm text-danger">
                Log out
              </button>
            )}
          </div>
        </nav>
      )}
    </header>
  )
}

import { useState } from 'react'
import { useStore } from '../../store/useStore'
import { useToast } from '../../context/toastContext'
import ConfirmDialog from '../ui/ConfirmDialog'
import Logo from './Logo'

export default function Footer() {
  const { resetDemoData } = useStore()
  const toast = useToast()
  const [confirmOpen, setConfirmOpen] = useState(false)

  return (
    <footer className="mt-16 border-t border-line bg-white">
      <div className="container-page flex flex-col gap-4 py-8 text-sm text-muted sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-col gap-2">
          <Logo />
          <p className="text-xs">Team 14 · SWE 363-01 · Front-end prototype with demo data.</p>
        </div>
        <div className="flex flex-wrap items-center gap-x-5 gap-y-2 text-xs">
          <span>© {new Date().getFullYear()} InternConnect</span>
          <button type="button" onClick={() => setConfirmOpen(true)} className="font-medium text-primary hover:underline">
            Reset demo data
          </button>
        </div>
      </div>
      <ConfirmDialog
        open={confirmOpen}
        title="Reset demo data?"
        message="All changes you made in this browser (applications, postings, saved listings ...) will be replaced with the original demo data."
        confirmLabel="Reset"
        danger
        onCancel={() => setConfirmOpen(false)}
        onConfirm={() => {
          resetDemoData()
          setConfirmOpen(false)
          toast.success('Demo data was reset.')
        }}
      />
    </footer>
  )
}

